            <Combobox.Input render={<Control data-testid="input" />} />
            <Combobox.Portal>
              <Combobox.Positioner>
                <Combobox.Popup>
                  <Combobox.List>
                    {(item: any) => (<Combobox.Item key={item.value} value={item}>{item.label}</Combobox.Item>)}
                  </Combobox.List>
                </Combobox.Popup>
              </Combobox.Positioner>
