import * as React from 'react';
import { expect, it, vi } from 'vitest';
import { render, fireEvent, screen, act, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

const out: Record<string, unknown> = {};
afterEach(() => cleanup());
afterAll(() => {
  // eslint-disable-next-line no-console
  console.log('PROBE ' + JSON.stringify(out, null, 1));
});

function countRenders(mode: any, withForm = false, validate: any = () => null) {
  const counts = { control: 0, root: 0 };
  function App() {
    const [value, setValue] = React.useState('');
    const tree = (
      <Field.Root
        name="x"
        validationMode={mode}
        validate={validate}
        render={(props) => {
          counts.root += 1;
          return <div {...props} />;
        }}
      >
        <Field.Control
          data-testid="control"
          value={value}
          onValueChange={setValue}
          render={(props) => {
            counts.control += 1;
            return <input {...props} />;
          }}
        />
      </Field.Root>
    );
    return withForm ? <Form>{tree}</Form> : tree;
  }
  render(<App />);
  const control = screen.getByTestId('control');
  fireEvent.change(control, { target: { value: 'a' } });
  const settled = { ...counts };
  fireEvent.change(control, { target: { value: 'ab' } });
  fireEvent.change(control, { target: { value: 'abc' } });
  return { control: (counts.control - settled.control) / 2, root: (counts.root - settled.root) / 2 };
}

it('render counts', () => {
  out.rendersPerKeystroke_default = countRenders(undefined);
  cleanup();
  out.rendersPerKeystroke_onChange = countRenders('onChange');
  cleanup();
  out.rendersPerKeystroke_onChange_form = countRenders('onChange', true);
  cleanup();
  out.rendersPerKeystroke_onChange_invalid = countRenders('onChange', false, () => 'bad');
});

